    fc.c03 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 3 FOLLOWING),
