    fc.c05 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 5 FOLLOWING),
    fc.c06 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 6 FOLLOWING),
