    fc.c10 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 10 FOLLOWING),
    fc.c11 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 11 FOLLOWING),
    fc.c12 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 12 FOLLOWING),
    fc.c13 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 13 FOLLOWING),
    fc.c14 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 14 FOLLOWING),
    fc.c15 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 15 FOLLOWING),
    fc.c16 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 16 FOLLOWING),
    fc.c17 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 17 FOLLOWING),
    fc.c18 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 18 FOLLOWING),
    fc.c19 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 19 FOLLOWING),
    fc.c20 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 20 FOLLOWING),
    fc.c21 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 21 FOLLOWING),
    fc.c22 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 22 FOLLOWING),
    fc.c23 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 23 FOLLOWING),
    fc.c24 AS SUM(fc.forecast_qty) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 24 FOLLOWING),
    fc.nz24 AS SUM(fc.forecast_nonzero_month) OVER (PARTITION BY EXCLUDING cal.month_start, cal.month_index ORDER BY cal.month_start ROWS BETWEEN 1 FOLLOWING AND 24 FOLLOWING),
    coverage_months AS CASE
